const D = { density:.5, scale:1, speed:1, energy:.6, hue:205, branch:.5, style:'frost', act:'grow', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const u = Math.min(width, height);
const st = P.style;
const intn = (K.intensity!=null?K.intensity:0.6);
const restartEvery = (P.act==='melt')?1:2;
const epoch = Math.floor((K.section||0)/restartEvery);
const cs = Math.max(2.5, u*0.0058*(0.55+P.scale));
const cols = Math.max(8, Math.floor(width/cs));
const rows = Math.max(8, Math.floor(height/cs));
const centerSeed = !(st==='coral' || P.act==='melt');

function paintBg(buf, st, hue){
  buf.noStroke();
  if (st==='ink') buf.background(40, 9, 88);
  else if (st==='coral') buf.background(192, 62, 9);
  else if (st==='circuit') buf.background(160, 45, 5);
  else buf.background(222, 58, 11);
  // faint vignette so it never reads flat
  buf.drawingContext.save();
  const g = buf.drawingContext.createRadialGradient(buf.width/2,buf.height/2,buf.width*0.1, buf.width/2,buf.height/2,buf.width*0.75);
  g.addColorStop(0,'rgba(255,255,255,0.04)'); g.addColorStop(1,'rgba(0,0,0,0.28)');
  buf.drawingContext.fillStyle=g; buf.drawingContext.fillRect(0,0,buf.width,buf.height);
  buf.drawingContext.restore();
}

function stamp(buf,cx,cy,cs,st,P,rad01,u){
  const x=(cx+0.5)*cs, y=(cy+0.5)*cs;
  const r = cs*(0.55 + P.branch*1.0);
  buf.push(); buf.noStroke();
  if (st==='circuit'){
    buf.drawingContext.shadowBlur=6; buf.drawingContext.shadowColor='rgba(80,255,150,0.6)';
    buf.fill((110+rad01*50)%360, 82, 96, 92);
    buf.rectMode(CENTER); buf.rect(x,y,r*0.9,r*0.9);
  } else if (st==='ink'){
    buf.fill(228, 14, 12, 78);
    buf.circle(x + (Math.sin(cx*12.9)*r*0.2), y + (Math.cos(cy*7.3)*r*0.2), r*(0.8+ (Math.sin(cx*3.1+cy)*0.3)));
  } else if (st==='coral'){
    buf.drawingContext.shadowBlur=5; buf.drawingContext.shadowColor='rgba(255,120,90,0.5)';
    buf.fill((14 + rad01*40)%360, 74, 96, 88); buf.circle(x,y,r);
  } else {
    buf.drawingContext.shadowBlur=8; buf.drawingContext.shadowColor='rgba(190,230,255,0.7)';
    buf.fill((P.hue + rad01*28)%360, Math.max(6,22-rad01*14), 92+rad01*8, 88); buf.circle(x,y,r);
  }
  buf.drawingContext.shadowBlur=0; buf.pop();
}

function spawn(S){
  const occ=S.occ, cols=S.cols, rows=S.rows;
  const o = occ.length? occ[(occ.length*S.rnd())|0] : [cols>>1, rows>>1];
  const ang = S.rnd()*Math.PI*2;
  const d = 4 + S.rnd()*11;
  let cx = Math.round(o[0]+Math.cos(ang)*d);
  let cy = Math.round(o[1]+Math.sin(ang)*d);
  cx = Math.max(1, Math.min(cols-2, cx));
  cy = Math.max(1, Math.min(rows-2, cy));
  return {cx:cx, cy:cy, life: 40 + (S.rnd()*70|0)};
}

const key = width+'x'+height+'|'+cs.toFixed(2)+'|'+P.seed+'|'+epoch+'|'+st;
if (S.key !== key){
  S.key = key;
  let z = ((P.seed*2654435761) ^ (epoch*40503)) >>> 0; z = (z+12345)>>>0;
  S.rnd = ()=>{ z=(z*1664525+1013904223)>>>0; return z/4294967296; };
  S.cols=cols; S.rows=rows; S.cs=cs;
  S.grid = new Uint8Array(cols*rows);
  S.occ = [];
  if (S.buf) S.buf.remove();
  S.buf = createGraphics(width,height);
  S.buf.colorMode(HSB,360,100,100,100);
  paintBg(S.buf, st, P.hue);
  const seeds = [];
  if (centerSeed) seeds.push([cols>>1, rows>>1]);
  else for (let i=0;i<Math.floor(5+P.density*7);i++) seeds.push([1+Math.floor(S.rnd()*(cols-2)), rows-2]);
  for (let s=0;s<seeds.length;s++){ const sx=seeds[s][0], sy=seeds[s][1]; S.grid[sy*cols+sx]=1; S.occ.push([sx,sy]); stamp(S.buf, sx, sy, cs, st, P, 0.02, u); }
  const NW = Math.floor(24 + P.density*130);
  S.walk = [];
  for (let i=0;i<NW;i++) S.walk.push(spawn(S));
  S.rmax = 3;
}

image(S.buf,0,0);

const grid=S.grid, cc=S.cols, rr=S.rows, occ=S.occ, cs2=S.cs, rnd=S.rnd;
const steps = Math.max(1, Math.round((2 + P.speed*4) * (0.6+intn) + A.bass*4));
noStroke();
if (st!=='ink') blendMode(ADD);
const wl = st==='ink' ? [228,22,20,42] : (st==='circuit'?[135,80,95,50]:(st==='coral'?[16,60,98,46]:[(P.hue)%360,26,98,46]));
for (let i=0;i<S.walk.length;i++){
  let w=S.walk[i];
  for (let s=0;s<steps;s++){
    const r=rnd(); w.cx += (r<0.34?-1:(r<0.67?0:1));
    const r2=rnd(); w.cy += (r2<0.34?-1:(r2<0.67?0:1));
    if (w.cx<1||w.cx>=cc-1||w.cy<1||w.cy>=rr-1||(--w.life)<=0){ S.walk[i]=spawn(S); w=S.walk[i]; continue; }
    const gi=w.cy*cc+w.cx;
    if (grid[gi]){ S.walk[i]=spawn(S); w=S.walk[i]; continue; }
    if (grid[gi-1]||grid[gi+1]||grid[gi-cc]||grid[gi+cc]){
      grid[gi]=1; occ.push([w.cx,w.cy]);
      const dc=w.cx-(cc>>1), dgr=w.cy-(rr>>1); const rad=Math.sqrt(dc*dc+dgr*dgr);
      if (rad>S.rmax) S.rmax=rad;
      stamp(S.buf, w.cx, w.cy, cs2, st, P, rad/Math.max(cc,rr), u);
      S.walk[i]=spawn(S); w=S.walk[i];
      break;
    }
  }
  const tw = wl[3]*(0.45 + 0.4*Math.sin(K.t*3+i*0.7) + A.treble*0.9);
  fill(wl[0],wl[1],wl[2], Math.max(0,tw));
  circle((w.cx+0.5)*cs2,(w.cy+0.5)*cs2, cs2*0.85);
}

if (centerSeed){
  const gx=(cc>>1)*cs2, gy=(rr>>1)*cs2;
  const gr=(S.rmax*cs2);
  noFill();
  const frH = st==='circuit'?135:(st==='ink'?228:(P.hue)%360);
  stroke(frH, st==='ink'?12:30, st==='ink'?40:100, 10+K.pulse*22+A.bass*16);
  strokeWeight(1.4+P.energy*2.2);
  circle(gx,gy, gr*2*(1.0+0.025*Math.sin(K.t*2)));
}

blendMode(BLEND);
drawingContext.shadowBlur = 0;
